"""Interleaved generation by the final twins (nl33w, step 300), generated by pairing/interleaved.py with 4-bit MLX
copies of the base models, greedy, on test-pool words never seen in training.

Top, the duplex word game: both twins write at once, one token per time step, and neither twin's input contains the
other's text. One real episode: each twin's prompt, then each twin's tokens at the time step the twin wrote them, with
the link on, and the receiver's tokens with the link cut. Arrows run to the receiver's word token from the sender's
prompt and from every sender token written before that step: at time step t a twin reads the partner's prompt and the
partner's tokens written before t (pairing/session.py). Bottom, the shared pen: one assistant message written by both
twins, one word per time step, the author changing every word; one real poem linked and cut. Right of each example,
the percent of all episodes, link on and link cut: the receiver writes the partner's word (duplex, evaluate.score);
the poem's last word, which the receiver writes, is the partner's word, and the holder did not write the word first
(pen).

The example episodes are the first, in episode order, that fit the page with Ember as the receiver, the word in
Ember's linked text and not in its cut text, and (duplex) the word absent from Quill's text, linked and cut; the pen
example's word differs from the duplex example's.

Reads results/magic-nl33w/results/interleaved.json and writes figures/interleaved.{svg,png,pdf} and
results/interleaved.json (the counts drawn and the episodes shown).
Usage: python figures/interleaved.py [GENERATIONS.json]
"""
import json
import re
import sys
from pathlib import Path

from chat_names import COOL, EMBER, INK, LINK, QUILL, RED, ROOT, SVG, WARM, mascot, pair_icon, width
from method_parts import TINT, arrow, check_shape, layout, link_down

SOURCE = ROOT / 'results/magic-nl33w/results/interleaved.json'
OUT = ROOT / 'results/interleaved.json'
STEM = ROOT / 'figures/interleaved'
COLOR = dict(quill=QUILL, ember=EMBER)
NAME = dict(quill='Quill', ember='Ember')
BASE = dict(quill='Qwen3-4B', ember='AFM-4.5B')
SENDER, RECEIVER = 'quill', 'ember'

W, M, G = 2300, 40, 30                 # page width, margin, gap
BODY, HEAD, PCT = 46, 56, 64           # text sizes: body, panel head, percents
LEAD = round(BODY * 1.3)               # line spacing
CH, CP, CG = 76, 16, 12                # chip height, chip padding, gap between chips
LABEL = 330                            # the row-label column
CW = 470                               # the percent column
ICON = 112
READS = ('Ember reads Quill’s', 'hidden states')     # the label of the arrows into the word


def has(text, w):
    return re.search(r'(?<![A-Za-z0-9])' + re.escape(w.lower()) + r'(?![A-Za-z0-9])', text.lower()) is not None


def shown(piece):
    """A token's text as drawn on its chip: without its leading or trailing spaces; a line break as ⏎."""
    t = piece.replace('\n', '⏎').strip()
    return t if t else '␣'


def word_ticks(tokens, v):
    """The time steps of the tokens that spell the first occurrence of v."""
    text, starts = '', []
    for t in tokens:
        starts.append(len(text))
        text += t['text']
    m = re.search(r'(?<![A-Za-z0-9])' + re.escape(v.lower()) + r'(?![A-Za-z0-9])', text.lower())
    if not m:
        return []
    return [t['tick'] for t, a in zip(tokens, starts) if a < m.end() and a + len(t['text']) > m.start()]


def pen_ok(c):
    return bool(c['ends'] and not c['holder_first'])


def counts(data):
    """Per game and condition: episodes where the receiver gets the partner's word, overall and per receiver."""
    out = {}
    for game, ok in (('relay_word', lambda c: bool(c['ok'])), ('pen_secret', pen_ok)):
        eps = data['episodes'][game]
        out[game] = {}
        for cond in ('link', 'cut'):
            out[game][cond] = dict(hits=sum(ok(e['conditions'][cond]) for e in eps), n=len(eps),
                                   by_receiver={x: dict(hits=sum(ok(e['conditions'][cond]) for e in eps
                                                                 if e['meta']['receiver'] == x),
                                                        n=sum(e['meta']['receiver'] == x for e in eps))
                                                for x in COLOR})
        if game == 'pen_secret':
            out[game]['holder_first'] = {c: sum(e['conditions'][c]['holder_first'] for e in eps)
                                         for c in ('link', 'cut')}
    return out


def eligible(data):
    """The candidate example episodes of each game, in episode order (see the module docstring)."""
    def duplex(e):
        link, cut = e['conditions']['link'], e['conditions']['cut']
        return (e['meta']['receiver'] == RECEIVER and link['ok'] and not cut['ok'] and not link['sender_wrote']
                and not cut['sender_wrote'])

    def pen(e):
        link, cut = e['conditions']['link'], e['conditions']['cut']
        return e['meta']['receiver'] == RECEIVER and pen_ok(link) and not cut['wrote']
    return ([e for e in data['episodes']['relay_word'] if duplex(e)],
            [e for e in data['episodes']['pen_secret'] if pen(e)])


class Page(SVG):
    """chat_names.SVG with each mascot picture embedded once and reused, so the page holds 4 pictures, not 40."""
    def mascot(self, name, x, y, size, flip=False):
        if name not in self.__dict__.setdefault('pictures', set()):
            self.pictures.add(name)
            self.add(f'<defs><image id="m-{name}" width="1" height="1" xlink:href="{mascot(name)}"/></defs>')
        turn = f' translate(1,0) scale(-1,1)' if flip else ''
        self.add(f'<use xlink:href="#m-{name}" transform="translate({x:.1f},{y:.1f}) scale({size}){turn}"/>')


def fits(panel, ep, n):
    try:
        panel(Page(1, 1), 0, ep, n, False)
    except ValueError:
        return False
    return True


def prompt_runs(text, value, owner):
    """Text runs for a prompt, the private word bold in its owner's colour on the owner's tint."""
    if value is None or value not in text:
        return [(text, INK, 400, None)]
    a = text.index(value)
    return [(text[:a], INK, 400, None), (value, COLOR[owner], 700, TINT[owner]),
            (text[a + len(value):], INK, 400, None)]


def text_block(s, x, y, w, runs, size=BODY, draw=True):
    """Word-wrapped runs from the top at y; returns the block's height."""
    lead = round(size * 1.3)
    lines = layout(runs, w, size)
    if draw:
        for k, line in enumerate(lines):
            by = y + size * 0.86 + k * lead
            for dx, word, color, weight, fill in line:
                if fill:
                    s.rect(x + dx - 8, by - size * 0.88, width(word, size, weight) + 16, size * 1.18, fill, 10)
            for dx, word, color, weight, fill in line:
                s.text(x + dx, by, word, size, weight, color)
    return (len(lines) - 1) * lead + size * 1.12


def prompts(s, y, ep, value, owner, draw=True, base=False):
    """The two prompts side by side, each in a card under its twin's icon and name (and base model); returns the
    cards' height."""
    cw = (W - 2 * M - G) / 2
    pad = 28
    hs = []
    for k, x in enumerate(('quill', 'ember')):
        cx = M + k * (cw + G)
        runs = prompt_runs(ep['task'][x], value if x == owner else None, owner)
        th = text_block(s, 0, 0, cw - 2 * pad, runs, draw=False)
        hs.append(pad + ICON + 14 + th + pad)
    h = max(hs)
    if draw:
        for k, x in enumerate(('quill', 'ember')):
            cx = M + k * (cw + G)
            s.rect(cx, y, cw, h, 'white', 28, COLOR[x], 4)
            s.mascot(x, cx + pad - 0.27 * ICON, y + pad, ICON)
            name = f'{NAME[x]}’s prompt' + (f' ({BASE[x]})' if base else '')
            s.text(cx + pad + 0.46 * ICON + 18, y + pad + ICON / 2 + 17, name, BODY, 700, COLOR[x])
            text_block(s, cx + pad, y + pad + ICON + 14, cw - 2 * pad,
                       prompt_runs(ep['task'][x], value if x == owner else None, owner))
    return h


def chip(s, x, y, w, text, owner, strong=False, fill=None):
    """A token or word chip sized to its text, centred in the column of width w at x."""
    cw = max(CH, width(text, BODY, 700 if strong else 400) + 2 * CP)
    s.rect(x + (w - cw) / 2, y, cw, CH, fill or TINT[owner], 16, RED if strong else COLOR[owner], 6 if strong else 3)
    s.text(x + w / 2, y + CH / 2 + BODY * 0.36, text, BODY, 700 if strong else 400, RED if strong else INK, 'middle')


def row_label(s, y, x_side, cut=False, text=None):
    """A twin's icon (link-cut pose when cut) and its name or text at the left of a row centred at y."""
    s.mascot(x_side + ('_cut' if cut else ''), M + 10 - 0.27 * ICON, y - ICON / 2, ICON)
    s.text(M + 10 + 0.46 * ICON + 16, y + 16, text or NAME[x_side], BODY, 700, COLOR[x_side])


def percent(c):
    return 100 * c['hits'] / c['n']


def bars(s, x, y, head, c_link, c_cut, ys, draw=True):
    """The percent column at x: its header lines, the last on the time-step line (baseline y), then one bar per
    condition centred on the rows at ys (vertical centres), link on red and link cut black, the percent at its end."""
    if max(width(t, BODY, 700) for t in head) > CW:
        raise ValueError(f'the bar header does not fit: {head}')
    if draw:
        for k, t in enumerate(head):
            s.text(x, y - (len(head) - 1 - k) * LEAD, t, BODY, 700, INK)
        full = CW - width('100%', PCT, 700) - 16
        for c, color, cy in ((c_link, RED, ys[0]), (c_cut, INK, ys[1])):
            w = full * percent(c) / 100
            if w:
                s.rect(x, cy - 30, w, 60, color, 8)
            s.text(x + w + (16 if w else 0), cy + 0.36 * PCT, f'{percent(c):.0f}%', PCT, 700, color)


def columns(widths, x0, right):
    """The left edge of each column of these widths from x0; an error when they pass right."""
    xs = [x0]
    for w in widths[:-1]:
        xs.append(xs[-1] + w + CG)
    if xs[-1] + widths[-1] > right:
        raise ValueError(f'the example is {xs[-1] + widths[-1] - right:.0f} px too wide')
    return xs


def duplex_panel(s, y, ep, n, draw=True):
    """The duplex example from the top at y; returns the panel's height."""
    v = ep['meta']['value']
    top = y
    y += text_block(s, M, y, W - 2 * M, [('Both write at once', INK, 700, None)], HEAD, draw) + G
    y += prompts(s, y, ep, v, SENDER, draw, base=True) + G + 10
    link, cut = ep['conditions']['link']['tokens'], ep['conditions']['cut']['tokens']
    rows = [('link', SENDER, link[SENDER]), ('link', RECEIVER, link[RECEIVER]), ('cut', RECEIVER, cut[RECEIVER])]
    hit = word_ticks(link[RECEIVER], v)
    last = max(len(link[RECEIVER]), len(cut[RECEIVER])) - 1
    more = width('…', BODY, 700) + CG
    # columns: the prompt, then time steps 0..last
    cols = [width('prompt', BODY) + 2 * CP] + [
        max([width(shown(r[t]['text']), BODY, 700) + 2 * CP for _, _, r in rows if t < len(r)] + [CH])
        for t in range(last + 1)]
    right = W - M - CW - G
    xs = columns(cols, M + LABEL, right - more)
    head = ('Writes the', 'partner’s word')
    y += (len(head) - 1) * LEAD                # the header lines above the time-step line
    axis = y + BODY * 0.86
    if draw:
        s.text(M + 10, axis, 'time step', BODY, 400, INK)
        for t in range(last + 1):
            s.text(xs[t + 1] + cols[t + 1] / 2, axis, str(t), BODY, 400, INK, 'middle')
    y += BODY * 1.12 + 24 + G
    gap = 150                                  # between the linked rows, room for the arrows
    ys = [y, y + CH + gap, y + 2 * CH + gap + 3 * G]
    if draw:
        s.rect(M, ys[0] - G, W - 2 * M, ys[1] - ys[0] + CH + 2 * G, WARM, 24)    # link on
        s.rect(M, ys[2] - G, W - 2 * M, CH + 2 * G, COOL, 24)                    # link cut
        # the link between the two twins of the link-on rows, and the conditions' names
        cx = M + 10 + 0.23 * ICON
        link_down(s, cx, ys[0] + CH / 2 + 0.42 * ICON, ys[1] + CH / 2 - 0.42 * ICON)
        s.text(cx + 40, (ys[0] + CH + ys[1]) / 2 + 16, 'Link on', BODY, 700, INK)
        for (cond, x, toks), ry in zip(rows, ys):
            if cond == 'cut':
                s.mascot(x + '_cut', M + 10 - 0.27 * ICON, ry + CH / 2 - ICON / 2, ICON)
                s.text(M + 10 + 0.46 * ICON + 16, ry + CH / 2 - 8, NAME[x], BODY, 700, COLOR[x])
                s.text(M + 10 + 0.46 * ICON + 16, ry + CH / 2 + 44, 'Link cut', BODY, 700, INK)
            else:
                row_label(s, ry + CH / 2, x)
            chip(s, xs[0], ry, cols[0], 'prompt', x, fill='white')
            for t in toks[:last + 1]:
                strong = cond == 'link' and x == RECEIVER and t['tick'] in hit
                chip(s, xs[t['tick'] + 1], ry, cols[t['tick'] + 1], shown(t['text']), x, strong)
            if len(toks) > last + 1:
                s.text(xs[-1] + cols[-1] + CG, ry + CH / 2 + 16, '…', BODY, 700, INK)
        # what Ember reads when it writes the word: Quill's prompt and Quill's tokens written before that step
        k = hit[0]
        tx = xs[k + 1] + cols[k + 1] / 2
        for j in range(k + 1):
            sx = xs[j] + cols[j] / 2
            arrow(s, [(sx, ys[0] + CH + 8), (tx + (sx - tx) * 0.18, ys[1] - 10)], LINK, 5, 20)
        for j, line in enumerate(READS):
            s.text(tx + 30, ys[0] + CH + 62 + 58 * j, line, BODY, 700, LINK)
    c = n['relay_word']
    if xs[hit[0] + 1] + cols[hit[0] + 1] / 2 + 30 + max(width(t, BODY, 700) for t in READS) > right:
        raise ValueError('the arrows\' label does not fit right of the word')
    bars(s, W - M - CW, axis, head, c['link'], c['cut'], [ys[1] + CH / 2, ys[2] + CH / 2], draw)
    return ys[2] + CH + G - top


def pen_panel(s, y, ep, n, draw=True):
    """The shared-pen example from the top at y; returns the panel's height."""
    v = ep['meta']['value']
    top = y
    y += text_block(s, M, y, W - 2 * M, [('Taking turns, one word each', INK, 700, None)], HEAD, draw) + G
    y += prompts(s, y, ep, v, ep['meta']['holder'], draw) + G + 10
    rows = [('link', ep['conditions']['link']['words']), ('cut', ep['conditions']['cut']['words'])]
    nw = max(len(w) for _, w in rows)
    cols = [max([width(shown(ws[j]['text']), BODY, 700) + 2 * CP for _, ws in rows if j < len(ws)] + [CH])
            for j in range(nw)]
    xs = columns(cols, M + 270, W - M - CW - G)        # the row label: the pair's icon
    head = ('Ends on the', 'partner’s word')
    y += (len(head) - 1) * LEAD                # the header lines above the time-step line
    axis = y + BODY * 0.86
    if draw:
        s.text(M + 10, axis, 'time step', BODY, 400, INK)
        for j in range(nw):
            s.text(xs[j] + cols[j] / 2, axis, str(j), BODY, 400, INK, 'middle')
    y += BODY * 1.12 + 20 + G
    isz = 96
    rh = isz + 6 + CH                          # a row: the author's icon over each word
    ys = [y, y + rh + 3 * G]
    for (cond, words), ry in zip(rows, ys):
        if not draw:
            continue
        s.rect(M, ry - G, W - 2 * M, rh + 2 * G, WARM if cond == 'link' else COOL, 24)
        pair_icon(s, M + 10, ry + 4, 116, cond, gap=0)
        s.text(M + 10, ry + rh - 8, 'Link on' if cond == 'link' else 'Link cut', BODY, 700, INK)
        for w in words:
            j = w['tick']
            s.mascot(w['author'] + ('_cut' if cond == 'cut' else ''), xs[j] + cols[j] / 2 - isz / 2, ry, isz)
            strong = cond == 'link' and w['author'] == ep['meta']['receiver'] and has(w['text'], v)
            chip(s, xs[j], ry + isz + 6, cols[j], shown(w['text']), w['author'], strong)
    c = n['pen_secret']
    bars(s, W - M - CW, axis, head, c['link'], c['cut'], [y + isz + 6 + CH / 2 for y in ys], draw)
    return ys[1] + rh + G - top


def draw(data, stem):
    n = counts(data)
    dups, pens = eligible(data)
    ex_dup = next(e for e in dups if fits(duplex_panel, e, n))
    ex_pen = next(e for e in pens if e['meta']['value'] != ex_dup['meta']['value'] and fits(pen_panel, e, n))
    s = Page(1, 1)
    h1 = duplex_panel(s, M, ex_dup, n, False)
    h2 = pen_panel(s, 0, ex_pen, n, False)
    H = round(M + h1 + 2 * G + h2 + M)
    check_shape(W, H)
    s = Page(W, H)
    duplex_panel(s, M, ex_dup, n)
    pen_panel(s, M + h1 + 2 * G, ex_pen, n)
    s.save(stem)
    return ex_dup, ex_pen, n


def main():
    src = Path(sys.argv[1]) if len(sys.argv) > 1 else SOURCE
    data = json.loads(src.read_text())
    ex_dup, ex_pen, n = draw(data, STEM)
    snap = dict(source=str(src.relative_to(ROOT)) if src.is_relative_to(ROOT) else str(src),
                checkpoint=data['checkpoint'], bridge_sha256=data['bridge_sha256'], backend=data['backend'],
                decoding=data['decoding'],
                metric=dict(relay_word='the receiver writes the partner\'s word (evaluate.score)',
                            pen_secret='the poem\'s last word, written by the receiver, is the partner\'s word, and '
                                       'the holder did not write the word first'),
                counts=n, examples=dict(relay_word=ex_dup['index'], pen_secret=ex_pen['index']))
    if src == SOURCE:
        OUT.write_text(json.dumps(snap, indent=1) + '\n')
    print(json.dumps({g: {c: f"{v['hits']}/{v['n']}" for c, v in n[g].items() if c in ('link', 'cut')} for g in n}))
    print(STEM.with_suffix('.png'))
    return 0


if __name__ == '__main__':
    sys.exit(main())
